"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type SliderProps = Omit<React.ComponentProps<"input">, "type" | "value" | "defaultValue" | "onChange" | "min" | "max" | "step" | "children"> & {
  /** What is being measured. It labels the range; spread and dynamics set it as the picture, so pass a string there. */
  label: React.ReactNode
  /**
   * dimension: the value is a dimension line from zero to the hand, your number in its gap.
   * spread: the label's letters are spread across the ruler as its marks, and the hand inks them as it passes.
   * dynamics: the label is as loud as the value (its weight follows the hand), over a scale from pp to ff.
   */
  variant?: "dimension" | "spread" | "dynamics"
  min?: number
  max?: number
  step?: number
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  /** Set after the number, as written: pass " kg" with its space, "%" without. */
  unit?: string
  /** Classes for the root. */
  className?: string
  /** Pins a state for documentation ("focus"); set on the root. */
  "data-force"?: string
}

/** The value a quarter-mark stands for, snapped to a step and free of float dust. */
const at = (min: number, max: number, step: number, fraction: number) => {
  const digits = (String(step).split(".")[1] ?? "").length
  return Number((min + Math.round(((max - min) * fraction) / step) * step).toFixed(digits))
}

const dynamics = ["pp", "p", "mp", "mf", "f", "ff"]

/**
 * A ruler with a hand. Native range, so arrows step, Page keys jump and Home / End go to the ends.
 * dimension (the default) draws the value as a dimension, after Paul Rand: a line from zero to the hand with your
 * number, in italic, in the gap; when the gap is too short for it, the number stands outside, past the far tick,
 * as a draughtsman sets it. spread and dynamics make the label the picture (see the variant prop).
 */
function Slider({
  label,
  variant = "dimension",
  min = 0,
  max = 100,
  step = 1,
  value: controlled,
  defaultValue,
  onValueChange,
  unit = "",
  className,
  id,
  "data-force": force,
  ...props
}: SliderProps) {
  const generated = React.useId()
  const inputId = id ?? generated
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue ?? min)
  const value = controlled ?? uncontrolled
  const p = max > min ? (value - min) / (max - min) : 0
  const word = typeof label === "string" && variant !== "dimension" ? label : null
  const shape = word ? variant : "dimension"
  const out = React.useRef<HTMLOutputElement>(null)
  const figure = React.useRef<HTMLSpanElement>(null)

  // The dimension must stay true to the hand, so a figure that doesn't fit its gap is set outside it.
  React.useLayoutEffect(() => {
    const o = out.current
    const f = figure.current
    if (shape !== "dimension" || !o || !f) return
    const place = () => o.toggleAttribute("data-outside", f.offsetWidth + parseFloat(getComputedStyle(o).fontSize) * 0.9 > o.clientWidth)
    place()
    const watch = new ResizeObserver(place)
    watch.observe(o)
    document.fonts?.ready.then(place, () => {})
    return () => watch.disconnect()
  }, [shape, value])

  return (
    <div data-slot="slider" data-variant={shape} data-force={force} className={cn("db-ruler", className)} style={{ "--p": p } as React.CSSProperties}>
      <label className={word ? "db-sr" : "db-label"} htmlFor={inputId}>
        {label}
      </label>
      {shape === "dynamics" ? (
        <output className="db-ruler-loud" htmlFor={inputId} style={{ "--chars": word?.length } as React.CSSProperties}>
          <span aria-hidden="true">{word}</span>{" "}
          <span className="db-ruler-yours">
            {value}
            {unit}
          </span>
        </output>
      ) : shape === "spread" ? (
        <output className="db-ruler-yours db-ruler-corner" htmlFor={inputId}>
          {value}
          {unit}
        </output>
      ) : (
        <output ref={out} className="db-ruler-value" htmlFor={inputId}>
          <span ref={figure}>
            {value}
            {unit}
          </span>
        </output>
      )}
      <div className="db-ruler-hand">
        {shape === "spread" ? (
          <span className="db-ruler-letters" aria-hidden="true">
            {[...(word ?? "")].map((l, i) => (
              <span key={i}>{l === " " ? " " : l}</span>
            ))}
          </span>
        ) : null}
        <input
          type="range"
          id={inputId}
          min={min}
          max={max}
          step={step}
          value={value}
          aria-valuetext={unit ? `${value}${unit}` : undefined}
          onChange={(e) => {
            const next = Number(e.target.value)
            if (controlled === undefined) setUncontrolled(next)
            onValueChange?.(next)
          }}
          {...props}
        />
      </div>
      <div className="db-ruler-scale" aria-hidden="true">
        {shape === "dynamics"
          ? dynamics.map((d, i) => (
              <span key={d} className="db-term" style={{ "--n": i / 5 } as React.CSSProperties} data-on={Math.round(p * 5) === i || undefined}>
                {d}
              </span>
            ))
          : [0, 0.25, 0.5, 0.75, 1].map((n) => (
              <span key={n} style={{ "--n": n } as React.CSSProperties}>
                {at(min, max, step, n)}
              </span>
            ))}
      </div>
    </div>
  )
}

export { Slider, type SliderProps }

@layer components {
  /* ── db-ruler ── slider: a ruler with a hand; the value is yours */
  .db-ruler {
    --p: 0.5;
    --thumb: 20px;
    --h: 40px; /* the hand's height; the track is as tall */
    --db-ruler-bg:
      linear-gradient(var(--db-ink), var(--db-ink)) calc(var(--thumb) / 2) 100% / calc((100% - var(--thumb)) * var(--p)) var(--db-stroke) no-repeat,
      linear-gradient(var(--db-pencil), var(--db-pencil)) calc(100% - var(--thumb) / 2) 100% / 1px 16px no-repeat,
      repeating-linear-gradient(90deg, var(--db-pencil) 0 1px, transparent 1px 25%) calc(var(--thumb) / 2) 100% / calc(100% - var(--thumb)) 16px no-repeat,
      repeating-linear-gradient(90deg, var(--db-rule-strong) 0 1px, transparent 1px 5%) calc(var(--thumb) / 2) 100% / calc(100% - var(--thumb)) 8px no-repeat,
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) calc(var(--thumb) / 2) 100% / calc(100% - var(--thumb)) 1px no-repeat;
    position: relative; display: block;
  }
  /* The value is a dimension, as Paul Rand drew them: a measured line from zero
     to the hand, ticked at both ends, with your number in the gap. */
  .db-ruler-value {
    display: flex; align-items: center; gap: 0.3em; position: relative;
    left: calc(var(--thumb) / 2); width: calc((100% - var(--thumb)) * var(--p));
    margin-top: var(--db-space-3);
    font-family: var(--db-expression); font-style: italic; font-size: var(--db-f); line-height: 1.05;
    color: var(--db-ink); font-variant-numeric: lining-nums;
    background:
      linear-gradient(var(--db-ink), var(--db-ink)) 0 55% / var(--db-hairline) 12px no-repeat,
      linear-gradient(var(--db-ink), var(--db-ink)) 100% 55% / var(--db-hairline) 12px no-repeat;
    transition: translate var(--db-andante) var(--db-spiccato);
  }
  .db-ruler-value > span { white-space: nowrap; }
  /* Too short a gap for the figure: the draughtsman's rule. The line stays true between its ticks and the figure
     stands outside, past the far one. */
  .db-ruler-value[data-outside] { gap: 0; }
  .db-ruler-value[data-outside] > span { position: absolute; inset-inline-start: calc(100% + 0.28em); }
  .db-ruler-value[data-outside]::after { display: none; }
  .db-ruler:has(input:active:not(:disabled)) :is(.db-ruler-value, .db-ruler-corner, .db-ruler-loud > .db-ruler-yours) { translate: 0 -5px; transition-duration: var(--db-moderato); }
  .db-ruler-value::before, .db-ruler-value::after { content: ""; flex: 1; height: var(--db-hairline); margin-top: 0.1em; background: var(--db-ink); }
  .db-ruler-hand { position: relative; }
  .db-ruler input[type="range"] {
    -webkit-appearance: none; appearance: none; display: block; position: relative;
    width: 100%; height: var(--h); margin: 0; background: transparent; cursor: pointer;
  }
  .db-ruler input[type="range"]::-webkit-slider-runnable-track { height: var(--h); background: var(--db-ruler-bg); }
  .db-ruler input[type="range"]::-moz-range-track { height: var(--h); background: var(--db-ruler-bg); }
  .db-ruler input[type="range"]::-moz-range-progress { background: transparent; }
  .db-ruler input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none; appearance: none; width: var(--thumb); height: var(--h); border: 0; border-radius: 0;
    background:
      radial-gradient(circle at 50% 5px, var(--db-accent) 3.6px, transparent 4.2px),
      linear-gradient(var(--db-ink), var(--db-ink)) 50% 100% / var(--db-stroke) calc(var(--h) - 10px) no-repeat;
  }
  .db-ruler input[type="range"]::-moz-range-thumb {
    width: var(--thumb); height: var(--h); border: 0; border-radius: 0;
    background:
      radial-gradient(circle at 50% 5px, var(--db-accent) 3.6px, transparent 4.2px),
      linear-gradient(var(--db-ink), var(--db-ink)) 50% 100% / var(--db-stroke) calc(var(--h) - 10px) no-repeat;
  }
  .db-ruler input[type="range"]:focus-visible { outline-offset: 8px; }
  .db-ruler[data-force~="focus"] { outline: 0; }
  .db-ruler[data-force~="focus"] input { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 8px; }
  .db-ruler-scale { position: relative; height: 1.6em; margin-top: var(--db-space-2); font-size: var(--db-pp); color: var(--db-pencil); font-variant-numeric: tabular-nums; }
  .db-ruler-scale > span { position: absolute; top: 0; left: calc(var(--thumb) / 2 + (100% - var(--thumb)) * var(--n)); translate: -50% 0; }
  .db-ruler:has(input:disabled) { opacity: 0.45; }
  .db-ruler:has(input:disabled) input { cursor: not-allowed; }
  .db-ruler-yours { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * var(--db-mf)); line-height: 1; color: var(--db-ink); font-variant-numeric: lining-nums tabular-nums; transition: translate var(--db-andante) var(--db-spiccato); }

  /* ── spread ── after "Renaissance.", whose words are spread to the edges: the label's letters are the ruler's marks,
     set out across its whole length. The hand stands through them and inks every letter it has passed, splitting the
     one it stands in, as "the uncreative" splits its word. Your number waits in the far corner. */
  .db-ruler[data-variant="spread"] {
    --h: 64px;
    --db-ruler-bg:
      linear-gradient(var(--db-ink), var(--db-ink)) calc(var(--thumb) / 2) 100% / calc((100% - var(--thumb)) * var(--p)) var(--db-stroke) no-repeat,
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) calc(var(--thumb) / 2) 100% / calc(100% - var(--thumb)) 1px no-repeat;
  }
  .db-ruler-corner { display: block; text-align: end; }
  .db-ruler-letters {
    position: absolute; inset-inline: calc(var(--thumb) / 2); bottom: 8px; display: flex; justify-content: space-between;
    font-size: var(--db-mf); line-height: 1; font-weight: 500; text-transform: uppercase; letter-spacing: 0;
    color: transparent; -webkit-background-clip: text; background-clip: text;
    background-image: linear-gradient(90deg, var(--db-ink) calc(var(--p) * 100%), var(--db-pencil) 0);
    pointer-events: none;
  }
  .db-ruler[data-variant="spread"] .db-ruler-scale > span:not(:first-child, :last-child) { display: none; }

  /* ── dynamics ── the score marks loudness pp to ff in italic under the notes. Here the label is as loud as the value:
     its weight and width follow the hand, from a whisper at zero to its heaviest at the top, and the nearest marking inks. */
  .db-ruler[data-variant="dynamics"] { container-type: inline-size; }
  .db-ruler-loud { display: flex; align-items: baseline; gap: var(--db-space-3); margin-bottom: var(--db-space-2); white-space: nowrap; }
  /* Sized from its letter count (--chars) so that at its heaviest it still fits one line: nothing reflows while you drag. */
  .db-ruler-loud > :first-child {
    font-size: max(var(--db-p), min(var(--db-f), calc((100cqi - 72px) / (var(--chars) * 0.76)))); line-height: 1.05; letter-spacing: var(--db-f-tr); color: var(--db-ink);
    font-weight: calc(100 + 800 * var(--p)); font-stretch: calc(62% + 63% * var(--p));
    transition: font-weight var(--db-allegro) var(--db-breath), font-stretch var(--db-allegro) var(--db-breath);
  }
  .db-ruler-loud > .db-ruler-yours { color: var(--db-graphite); }
  .db-ruler[data-variant="dynamics"] .db-ruler-scale { font-size: var(--db-p); height: 1.4em; }
  .db-ruler[data-variant="dynamics"] .db-ruler-scale > span { font-variant-numeric: normal; transition: color var(--db-allegro); }
  .db-ruler[data-variant="dynamics"] .db-ruler-scale > [data-on] { color: var(--db-ink); }

  /* Right to left the ruler turns with the text: zero is on the right and the hand fills leftward. */
  .db-ruler:is([dir="rtl"], [dir="rtl"] *) {
    --db-ruler-bg:
      linear-gradient(var(--db-ink), var(--db-ink)) right calc(var(--thumb) / 2) bottom 0 / calc((100% - var(--thumb)) * var(--p)) var(--db-stroke) no-repeat,
      linear-gradient(var(--db-pencil), var(--db-pencil)) left calc(var(--thumb) / 2) bottom 0 / 1px 16px no-repeat,
      repeating-linear-gradient(270deg, var(--db-pencil) 0 1px, transparent 1px 25%) right calc(var(--thumb) / 2) bottom 0 / calc(100% - var(--thumb)) 16px no-repeat,
      repeating-linear-gradient(270deg, var(--db-rule-strong) 0 1px, transparent 1px 5%) right calc(var(--thumb) / 2) bottom 0 / calc(100% - var(--thumb)) 8px no-repeat,
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) right calc(var(--thumb) / 2) bottom 0 / calc(100% - var(--thumb)) 1px no-repeat;
  }
  .db-ruler[data-variant="spread"]:is([dir="rtl"], [dir="rtl"] *) {
    --db-ruler-bg:
      linear-gradient(var(--db-ink), var(--db-ink)) right calc(var(--thumb) / 2) bottom 0 / calc((100% - var(--thumb)) * var(--p)) var(--db-stroke) no-repeat,
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) right calc(var(--thumb) / 2) bottom 0 / calc(100% - var(--thumb)) 1px no-repeat;
  }
  .db-ruler:is([dir="rtl"], [dir="rtl"] *) .db-ruler-letters { background-image: linear-gradient(270deg, var(--db-ink) calc(var(--p) * 100%), var(--db-pencil) 0); }
  .db-ruler:is([dir="rtl"], [dir="rtl"] *) .db-ruler-value { left: auto; right: calc(var(--thumb) / 2); }
  .db-ruler:is([dir="rtl"], [dir="rtl"] *) .db-ruler-scale > span { left: auto; right: calc(var(--thumb) / 2 + (100% - var(--thumb)) * var(--n)); translate: 50% 0; }

  /* Forced colours: the ruler restates its tokens in system colours, so every drawn tick and the hand survive. */
  @media (forced-colors: active) {
    .db-ruler { forced-color-adjust: none; color: CanvasText; --db-ink: CanvasText; --db-graphite: CanvasText; --db-pencil: GrayText; --db-rule-strong: GrayText; --db-accent: Highlight; }
  }
}
